"""M19 freeze intervention-supervision design before generating training responses."""
from pathlib import Path
import json,hashlib
P=Path(__file__).resolve().parent/'validation'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 mp=P/'context_training_results.json';m=json.loads(mp.read_text());oldp=P/'context_training_protocol.json';old=json.loads(oldp.read_text());ep=P/'context_expansion_protocol.json';expanded={x['id']:x for x in json.loads(ep.read_text())['rows']};starts=[x for x in m['models'] if x['arm']=='expanded_context'];assert len(starts)==4
 for entry in starts:assert sha(Path(entry['path']))==entry['sha256']
 schedules={}
 for seed in [71,72]:
  schedule=old['schedules'][str(seed)];counts={};targets=[]
  for u in schedule['task_updates']:
   family=u['family'];n=counts.get(family,0);region='prefix' if n%2==0 else 'task';counts[family]=n+1;row=expanded[u['expanded_pair_id']];assert row['training_eligible'];groups=[int(hashlib.sha256(f'M19:{seed}:{u["task_update"]}:{row["id"]}:{epidx}'.encode()).hexdigest(),16)%32 for epidx in [0,1]];targets.append(dict(u,region=region,endpoint_groups=groups))
  schedules[str(seed)]=dict(natural_documents=schedule['natural_documents'],task_updates=targets)
 p=dict(status='frozen_before_target_generation',source_sha256=sha(Path(__file__)),M18_results_sha256=sha(mp),M18_protocol_sha256=sha(oldp),expansion_sha256=sha(ep),initial_models=starts,schedules=schedules,arms=['intact_KL','intact_KL_plus_response'],steps=120,learning_rate=.0003,optimizer='Fresh Adam, unit decoder columns after each step, frozen normalization and native weights.',target_design='Reuse M18 training-only expandedpair/source schedules and naturaldocuments. Six taskupdates/family, exactly3prefix/3task. One fixed hash-selected group per endpoint, same group index for scalar/block at a seed. Decode delta from starting M18-expanded checkpoint on native MLP1write. Hold delta detached/fixed throughout training. No group rejection if inactive, zero directions retained. All gate eligibility from M17 train/train only.',response_loss='For final-position logits, let rN=logsoftmax(native perturbed)-logsoftmax(native intact); rF similarly for reconstructed perturbed/intact using identical frozen delta. R=sum_v pN_intact(v)*(rF(v)-rN(v))^2. Differentiate BOTH reconstructed forwards; native outputs and delta detached. Intact loss K=mean all-position/full-vocabulary KL(native||reconstruction).',calibration='Before optimization, compute Kbar and Rbar at starting checkpoint over all120 scheduled task endpoints, equally weighted including repeats/noops. Freeze lambda=Kbar/Rbar so initial task-average KL and weighted response contributions match. If either nonpositive or nonfinite, fail prerequisite rather than replace/clip. Natural updates use only KL. Task objective control K vs treatment K+lambda*R, equal endpoint weights. This is training-only scaling, not eval-based tuning; gradients and total objective scale need not match.',evaluation='Initial and final output fidelity on unchanged M18 inventory. Causal validation retains M18/M11-based 704 frozen native directions, source/context/site/group selection and teacher effects unchanged, so training perturbations do not define evaluation deltas. Compare both regions, allthree nontrainingquadrants, family weighting, raw errors and native energy denominators. Whole-task exclusions preserved.',gradient_checks='For each startingmodel and eachregion, first scheduled endpoint with nonzero delta and positive response loss. Check q=native identity response, finite differences at eps1e-3 and3e-4 along normalized analytic gradient scaled by qnorm; relative tolerance3% or absolute1e-6. Check both reconstructed branches require gradients and frozen native parameters/delta do not. Then test finite nonzero featurizer gradients through selectedsupport. Gate index derivatives are not claimed.',stopping_rule='Generate targets/calibrate/audit before training. Exactly8fits at120updates; no responseweight/group/template/width search. Train-only scaling may create numericaldifficulty; failures retained and any repair documented separately. Causal-transfer gain is necessary evidence, not semanticunit/newtaskdiscovery proof.')
 op=P/'response_supervision_protocol.json'
 if op.exists():assert json.loads(op.read_text())==p
 else:op.write_text(json.dumps(p,indent=2)+'\n')
 print('Frozen4starts;480scheduledtraining-endpointperturbations;8futurefits')
if __name__=='__main__':main()
